import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const resurrectionPhysicalScenarios=['resurrection-ordinary','resurrection-dedicated','resurrection-chanted-dedicated'] as const;
export type ResurrectionPhysicalScenario=typeof resurrectionPhysicalScenarios[number];
export function isResurrectionPhysicalScenario(name:string):name is ResurrectionPhysicalScenario{return (resurrectionPhysicalScenarios as readonly string[]).includes(name);}
export function makeResurrectionPhysicalScenario(name:ResurrectionPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;victim?:string;sourceFaction?:'GOOD'|'EVIL';terminal?:boolean}={}){
 let s=createGame(players,entropy(),{startingSeat:1});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string],victim=options.victim??'大神官ジル';assignCharacter(s,a,options.owner??'邪祭ウーノス');assignCharacter(s,b,victim);assignCharacter(s,c,victim==='有翼人のティア'?'早駆けのランカスター':'有翼人のティア');assignCharacter(s,d,options.sourceFaction==='GOOD'?'魔導王ガイナス':victim==='侍大将のシン'?'白魔術師シェリム':'侍大将のシン');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[a]!.permanent!.magic_level=20+(options.level??10)-gameStats(s,a).magic_level;s.players[a]!.permanent!.spirit=20+6-gameStats(s,a).spirit;for(const id of [b,c])s.players[id]!.permanent!.endurance=100+4-gameStats(s,id).endurance;
 const card=takeCard(s,a,'a2-p13-r3c1'),book=takeCard(s,b,'魔導書'),guard=takeCard(s,b,'兵士'),fire=takeCard(s,d,'a2-p15-r3c2'),ice=takeCard(s,d,'a2-p12-r2c2'),fate=takeCard(s,d,'命運凶変'),conversion=(options.sourceFaction||victim==='魔聖母ディア')?takeCard(s,d,options.sourceFaction==='GOOD'?'a2-p04-r1c1':'a2-p04-r1c2'):null;for(const id of [a,b,c,d])trimHand(s,id,card,book,guard,fire,ice,fate,...(conversion?[conversion]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand,dice=Array(100).fill(1)){const input={actorId,command},e={...entropy(),dice},r=transition(s,input,e);if(!r.ok)throw Error(`RESURRECTION_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('RESURRECTION_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('RESURRECTION_IDS');}
 function advanceTo(target:string){for(let n=0;n<300;n++){if(options.terminal&&s.outcome)return;const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===target)return;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>![card,fire,ice,fate,conversion].includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('RESURRECTION_PHASE');}throw Error('RESURRECTION_TURNS');}
 for(const id of [a,b,c,d]){if(id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(b,{type:'START_TURN'});act(b,{type:'CHOOSE_DRAW',draw:false});act(b,{type:'PLAY_TURN_CARD',cardInstanceIds:[book]});advanceTo(d);if(conversion){act(a,{type:'REVEAL_CHARACTER'});while(s.windows?.length){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}act(d,{type:'PLAY_TURN_CARD',cardInstanceId:conversion as 'a2-p04-r1c1',targetId:a});while(s.windows?.length){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'},Array(100).fill(6));}if(s.players[a]!.faction!==(options.sourceFaction??'EVIL')||!s.events.some(e=>e.type==='FACTION_CHANGED'&&e.actorId===a))throw Error('RESURRECTION_CONVERSION');advanceTo(d);}act(d,{type:'ATTACK',cardInstanceId:fire,targetIds:[b],dedicated:false});advanceTo(d);if(options.terminal&&s.outcome)return s;if(s.players[b]!.presence!=='dead')throw Error('RESURRECTION_FIRST_DEATH');act(d,{type:'ATTACK',cardInstanceId:ice,targetIds:[c],dedicated:false});advanceTo(a);if(s.players[c]!.presence!=='dead'||s.outcome)throw Error('RESURRECTION_SECOND_DEATH');return s;
}
